module ActiveSupport;module Testing;module ConstantStubbing;def stub_const(mod,constant,new_value,exists:true)if exists;begin old_value=mod.const_get(constant,false);mod.send(:remove_const,constant);mod.const_set(constant,new_value);yield ;ensure mod.send(:remove_const,constant);mod.const_set(constant,old_value);end;else if mod.const_defined?(constant);raise NameError,"already defined constant #{constant} in #{mod.name}";end;begin mod.const_set(constant,new_value);yield ;ensure mod.send(:remove_const,constant);end;end;end;end;end;end
